// Jedno zgłoszenie (formularz n8n, landing tekst/głos, Fireflies, Gmail) -> wspólny format dla reszty workflow.
// Bierzemy WSZYSTKIE źródła treści naraz (transkrypcja nagrania, tekst, persona, wiadomość), a nie tylko pierwsze znalezione.
const j = $json;
const b = j.body && typeof j.body === 'object' ? j.body : j; // webhook trzyma dane w body
const str = (v) => (v == null ? '' : typeof v === 'object' ? String(v.text ?? v.value ?? '') : String(v)).trim();
const pick = (...vals) => vals.map(str).find(Boolean) || '';
const get = (k) => b[k] ?? j[k];

let source = 'inne';
try {
  source = { Form: 'formularz n8n', 'Website form': 'formularz WWW', 'Transkrypcja z fireflies': 'Fireflies', 'Gmail Trigger': 'Gmail' }[$prevNode.name] || $prevNode.name;
} catch {}
if (b.source) source = `${source} (${b.source}${b.mode ? `, ${b.mode}` : ''})`;

// --- treść: każda część osobno, z etykietą ---
const parts = [];
const add = (label, v) => {
  const t = str(v);
  if (t && !parts.some((p) => p.text === t)) parts.push({ label, text: t });
};

// Fireflies: podsumowanie i wypowiedzi
const ff = b.data?.transcript || b.transcript || {};
add('Podsumowanie spotkania (Fireflies)', b.summary?.overview || ff.summary?.overview);
const sentences = b.sentences || ff.sentences;
if (Array.isArray(sentences)) add('Transkrypcja spotkania', sentences.map((s) => `${s.speaker_name || s.speaker || ''}: ${s.text || s.raw_text || ''}`).join('\n'));

// Landing: nagranie głosowe, tekst klienta, przykładowa persona
const voice = b.voice || {};
add(`Transkrypcja nagrania głosowego${voice.seconds ? ` (${voice.seconds} s)` : ''}`, voice.transcript || voice.sampleTranscript);
add('Tekst od klienta', b.brief?.text);
add('Opis potrzeb', pick(get('Opis potrzeb'), get('message'), get('wiadomosc'), get('wiadomość'), get('opis'), get('notes'), get('description')));
if (typeof b.transcript === 'string') add('Transkrypcja', b.transcript);
add('Treść', pick(get('text'), get('textPlain'), get('snippet')));
if (b.tryItAs?.text) add(`Przykładowa persona wybrana na stronie: ${b.tryItAs.label || b.tryItAs.persona || ''}`, b.tryItAs.text);

const subject = pick(get('Subject'), get('subject'));
if (subject && /Gmail/.test(source)) parts.unshift({ label: 'Temat e-maila', text: subject });

const text = parts.map((p) => `## ${p.label}\n${p.text}`).join('\n\n').slice(0, 20000);

// --- kontakt ---
let email = pick(get('E-mail'), get('email'), get('mail'), get('From'), get('from'));
const m = email.match(/[\w.+-]+@[\w-]+\.[\w.-]+/);
email = m ? m[0] : email;

// --- podpowiedzi -> id kafelków (wybór klienta ma pierwszeństwo przed personą demo) ---
const low = (s) => str(s).toLowerCase();
const asTile = (prefix, v) => (v ? (v.startsWith(`${prefix}:`) ? v : `${prefix}:${v}`) : null);
const segRaw = low(pick(b.brief?.segment, get('Segment'), get('segment'), b.tryItAs?.segment));
const roleRaw = low(pick(b.brief?.role, b.pickedRole, get('Twoja rola'), get('Rola'), get('role'), b.tryItAs?.role));
const prodRaw = low(pick(get('Produkt'), get('product'), get('produkt')));
const hints = {
  segment: /^(segment:)?(law-firm|in-house|public-sector|finance|tax-advisors|notaries|mass-claims)$/.test(segRaw) ? asTile('segment', segRaw)
    : /kancel|law/.test(segRaw) ? 'segment:law-firm' : /dział|dzial|in-house|firm/.test(segRaw) ? 'segment:in-house' : /publi|urząd|urzad/.test(segRaw) ? 'segment:public-sector' : null,
  role: /^(role:)?(board|champion|cto|gc|budget|dpo)$/.test(roleRaw) ? asTile('role', roleRaw)
    : /zarz|partner|board|dyrek|prezes|ceo/.test(roleRaw) ? 'role:board' : /prawnik|lider|champion|radca|adwokat/.test(roleRaw) ? 'role:champion' : null,
  product: /^(product:)?(saas|vault|on-prem)$/.test(prodRaw) ? asTile('product', prodRaw)
    : /on-?prem|serwer/.test(prodRaw) ? 'product:on-prem' : /saas|chmur/.test(prodRaw) ? 'product:saas' : /vault/.test(prodRaw) ? 'product:vault' : null,
};
for (const k of Object.keys(hints)) if (!hints[k]) delete hints[k];

return {
  json: {
    source,
    company: pick(get('Firma'), get('company'), get('firma'), get('organization'), get('organizacja'), get('client'), get('klient')),
    contact_name: pick(get('Imię i nazwisko'), get('name'), get('imie'), get('contact'), get('kontakt')) || pick(get('From'), get('from')).replace(/<.*>/, '').trim(),
    email,
    hints,
    price: pick(get('Cena'), get('price'), get('cena')),
    language: str(b.language),
    parts: parts.map((p) => p.label),
    text,
    received_at: new Date().toISOString(),
  },
};

// Odpowiedź AI -> sprawdzone kafelki (1 rola, 1 segment, 1 produkt, 1–5 problemów).
// Gdy odpowiedź jest zła, a to jeszcze nie 3. próba, odsyłamy AI opis błędu (retry: true) i AI poprawia się samo.
const MAX_TRIES = 3;
const attempt = $runIndex + 1;
const lead = $('Normalizuj zgłoszenie').first().json;
const tiles = $('Kontekst dla AI').first().json.tiles;
const raw = String($json.output ?? $json.text ?? '');

// Tolerancyjny parser: wycina JSON z tekstu i naprawia typowe błędy modeli.
function parseLoose(text) {
  let s = text.replace(/```(?:json)?/gi, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a < 0 || b <= a) throw new Error('w odpowiedzi nie ma obiektu JSON');
  s = s.slice(a, b + 1);
  const tries = [
    (x) => x,
    (x) => x.replace(/„([^"„”\n]*)"/g, '„$1”'), // „cytat" -> „cytat”
    (x) => x.replace(/[“”]/g, '\\"').replace(/„/g, '\\"'), // typograficzne cudzysłowy
    (x) => x.replace(/,\s*([}\]])/g, '$1'), // przecinek przed } lub ]
  ];
  let cur = s;
  let lastErr;
  for (const fix of tries) {
    cur = fix(cur);
    try { return JSON.parse(cur); } catch (e) { lastErr = e; }
  }
  throw new Error(`niepoprawny JSON (${lastErr.message})`);
}

const problems = [];
let ai = {};
try {
  ai = parseLoose(raw);
} catch (e) {
  problems.push(e.message);
}

const ids = new Set(tiles.map((t) => t.id));
const cat = (id) => tiles.find((t) => t.id === id)?.category;
const okIn = (id, category) => id && ids.has(id) && cat(id) === category;

if (!problems.length) {
  for (const k of ['role', 'segment', 'product']) {
    if (ai[k] && !okIn(ai[k], k)) problems.push(`"${k}": "${ai[k]}" nie jest kafelkiem kategorii ${k} z listy`);
  }
  const badPains = (Array.isArray(ai.pains) ? ai.pains : []).filter((id) => !okIn(id, 'pain'));
  if (badPains.length) problems.push(`"pains" zawiera nieistniejące kafelki: ${badPains.join(', ')}`);
  if (!(Array.isArray(ai.pains) && ai.pains.some((id) => okIn(id, 'pain')))) problems.push('"pains" musi mieć 1–5 kafelków pain:… z listy');
}

if (problems.length && attempt < MAX_TRIES) {
  return [{ json: { retry: true, attempt, problems, raw: raw.slice(0, 4000) } }];
}
if (!Object.keys(ai).length) throw new Error(`AI po ${attempt} próbach nie zwróciło poprawnego JSON-a: ${problems.join('; ')}. Odpowiedź: ${raw.slice(0, 300)}`);

// Ostatnia próba albo wszystko OK: bierzemy to, co poprawne, resztę uzupełniamy bezpiecznymi domyślnymi.
const one = (category, ...candidates) => candidates.find((id) => okIn(id, category))
  || tiles.find((t) => t.category === category)?.id;
const role = one('role', lead.hints.role, ai.role, 'role:champion');
const segment = one('segment', lead.hints.segment, ai.segment);
const product = one('product', lead.hints.product, ai.product, 'product:vault');
let pains = [...new Set((Array.isArray(ai.pains) ? ai.pains : []).map(String))].filter((id) => okIn(id, 'pain')).slice(0, 5);
if (!pains.length) pains = [tiles.find((t) => t.category === 'pain').id];

const client = String(lead.company || ai.client || 'Klient').trim();
return [{
  json: {
    retry: false,
    attempt,
    warnings: problems,
    request: { client, tiles: [role, segment, product, ...pains], ...(lead.price ? { price: lead.price } : {}) },
    client,
    analysis: ai.analysis || null,
    summary: String(ai.summary || ''),
    reasons: ai.reasons || {},
  },
}];

// Kafelki z Offer Studio -> prompt dla AI. AI wybiera kafelki, a ofertę buduje Studio (POST /api/offers/generate).
const lead = $('Normalizuj zgłoszenie').first().json;
const tiles = ($json.data || []).filter((t) => t.status !== 'soon');
const byCat = (cat) => tiles.filter((t) => t.category === cat)
  .map((t) => `- ${t.id} | ${t.label} | ${String(t.description || '').replace(/\s+/g, ' ')}`).join('\n');

const prompt = `# Zgłoszenie (${lead.source})
Firma: ${lead.company || '(nie podano)'}
Kontakt: ${lead.contact_name || '-'} ${lead.email ? `<${lead.email}>` : ''}
Podpowiedzi z formularza: ${JSON.stringify(lead.hints)}
Treść (${(lead.parts || []).length} części):
"""
${lead.text || '(brak treści)'}
"""

# Kafelki: rola (dokładnie 1)
${byCat('role')}

# Kafelki: segment (dokładnie 1)
${byCat('segment')}

# Kafelki: produkt (dokładnie 1)
${byCat('product')}

# Kafelki: problemy (1–5, najważniejsze najpierw)
${byCat('pain')}

Odpowiedz wyłącznie obiektem JSON według schematu z instrukcji systemowej.`;

return [{ json: { prompt, tiles: tiles.map((t) => ({ id: t.id, category: t.category })) } }];

// Krótkie podsumowanie dla zespołu (Discord) + PDF w binarnym polu "data".
const plan = $('Przygotowanie scenariusza').first().json;
const lead = $('Normalizuj zgłoszenie').first().json;
const check = $('Sprawdź treść').last().json;
const offer = $('Zapisz treść').first().json;
const STUDIO_URL = 'https://studio.bizhack.trygaius.com';
const link = `${STUDIO_URL}/#/offers/${encodeURIComponent(offer.id)}`;

const slides = offer.slides || [];
const written = slides.filter((s) => s.origin && s.origin.written_by).map((s) => s.origin.label || s.frame);
const comparison = slides.find((s) => s.frame === 'tool-comparison');

const message = [
  `📄 Nowa oferta: **${offer.name || plan.client}**`,
  `Źródło: ${lead.source}${lead.contact_name ? ` · ${lead.contact_name}` : ''}${lead.email ? ` <${lead.email}>` : ''}`,
  `Kafelki: ${plan.request.tiles.join(', ')}`,
  `Treść od AI: ${written.length ? written.join(', ') : 'brak (teksty domyślne)'}${comparison ? ` · porównanie z narzędziem: ${comparison.hidden ? 'ukryte' : 'pokazane'}` : ''}`,
  check.warnings && check.warnings.length ? `⚠️ Pominięte przy zapisie (zostały teksty domyślne): ${check.warnings.slice(0, 5).join('; ')}` : '',
  plan.summary ? `\n${plan.summary}` : '',
  `\nEdycja w Offer Studio: ${link}`,
].filter(Boolean).join('\n');

return [{
  json: { offer_id: offer.id, offer_name: offer.name, offer_url: link, pdf_url: `${STUDIO_URL}/api/offers/${encodeURIComponent(offer.id)}/pdf`, tiles: plan.request.tiles, written, warnings: check.warnings || [], message },
  binary: $input.first().binary,
}];

// Samopoprawka: ten sam prompt + lista błędów z poprzedniej odpowiedzi. Wraca do AI Agent.
const base = $('Kontekst dla AI').first().json.prompt;
return [{
  json: {
    prompt: `${base}

# Poprawka (próba ${$json.attempt + 1})
Twoja poprzednia odpowiedź nie przeszła walidacji:
${$json.problems.map((p) => `- ${p}`).join('\n')}

Poprzednia odpowiedź:
"""
${$json.raw}
"""

Zwróć cały obiekt JSON jeszcze raz, poprawiony. Używaj wyłącznie id kafelków z listy. W tekstach nie używaj znaku " (cytaty pisz w « »).`,
  },
}];

// Pola slajdów z Offer Studio (GET /api/offers/:id/content) + zgłoszenie -> prompt dla AI, które pisze treść oferty.
// Opisy pól (co napisać, limit znaków, liczba kart) są w scenariuszu w Offer Studio (zakładka Scenarios), nie tutaj.
const lead = $('Normalizuj zgłoszenie').first().json;
const plan = $('Przygotowanie scenariusza').first().json;
const ctx = $json;

const describe = (f) => f.kind === 'text'
  ? `tekst, maks. ${f.max} znaków. ${f.hint}\n    domyślnie: ${JSON.stringify(f.current)}`
  : `lista ${f.min}–${f.max} pozycji. ${f.hint}\n    kolumny: ${Object.entries(f.columns).map(([k, c]) => `${k} (maks. ${c.max} znaków): ${c.hint}`).join('; ')}\n    domyślnie: ${JSON.stringify(f.current)}`;
// Biblioteka Offer Studio: co wiemy o bólach klienta i jak je rozwiązujemy (fakty o produkcie).
const ev = ctx.evidence || { pains: [] };
const evidence = ev.pains.map((p) => [
  `## ${p.label}${p.description ? `: ${p.description}` : ''}`,
  p.typical_quotes?.length ? `Typowe cytaty innych klientów (NIE tego klienta): ${p.typical_quotes.map((q) => `‘${q}’`).join('; ')}` : '',
  p.no_solution ? 'Rozwiązanie: brak w bibliotece. Nie obiecuj rozwiązania tego bólu.' : '',
  ...p.solutions.map((s) => `- rozwiązanie: ${s.title}. ${s.text}${s.effect ? ` Efekt: ${s.effect}` : ''}${s.value ? ` Wartość: ${s.value}` : ''}`),
  ...p.proof.map((s) => `- dowód (${s.type}): ${s.title}. ${s.text}`),
].filter(Boolean).join('\n')).join('\n\n');

const slides = ctx.slides.map((s) => [
  `## ${s.step} (${s.label})${s.optional ? ' [OPCJONALNY: napisz go tylko, gdy ma podstawę w zgłoszeniu; inaczej {"hide": true}]' : ''}`,
  ...Object.entries(s.fields).map(([k, f]) => `- ${k}: ${describe(f)}`),
].join('\n')).join('\n\n');

const prompt = `# Klient
Firma: ${ctx.client}
Produkt w ofercie: ${ctx.product_name}
Kafelki: ${(ctx.client_tiles || []).map((t) => `${t.label || t.id}`).join(', ')}
Notatka handlowca (z analizy zgłoszenia): ${plan.summary || '-'}

# Odbiorca prezentacji: ${ctx.reader ? ctx.reader.label : 'nieznany'}
${ctx.reader ? [ctx.reader.description, ctx.reader.brief].filter(Boolean).join('\n') : 'Pisz neutralnie.'}

# Zgłoszenie (${lead.source})
"""
${lead.text || '(brak treści)'}
"""

# Biblioteka: bóle klienta i nasze rozwiązania (segment: ${ev.segment ? ev.segment.label : '-'}, produkt: ${ev.product ? ev.product.label : '-'})
${evidence || '(brak)'}

# Slajdy i pola do napisania
${slides}

Odpowiedz wyłącznie obiektem JSON według schematu z instrukcji systemowej.`;

return [{ json: { prompt, offer_id: ctx.offer_id, context: ctx } }];

options.systemMessage:
Jesteś handlowcem Gaius-Lex (Legal AI dla kancelarii, działów prawnych i sektora publicznego). Piszesz treść prezentacji ofertowej dla jednego klienta na podstawie jego zgłoszenia (transkrypcja rozmowy, e-mail albo formularz). Prezentacja jest PO ANGIELSKU: każde pole piszesz po angielsku, nawet gdy zgłoszenie jest po polsku. Nazwy własne (firma, osoby, narzędzia) zostaw w oryginale.

Zasady:
1. Pisz tylko na podstawie zgłoszenia. Nie wymyślaj faktów: liczb, nazwisk, dat, narzędzi, obaw. Gdy w zgłoszeniu nie ma podstawy do pola, pomiń to pole: zostanie tekst domyślny.
2. Trzymaj się opisu pola i limitu znaków. Krótko i rzeczowo, bez przymiotników sprzedażowych, bez straszenia. Słowa klienta są lepsze niż ogólniki.
3. Nazwę produktu bierz z "Produkt w ofercie".
4. use-areas: te same obszary i w tej samej kolejności co areas na slajdzie starting-point.
5. tool-comparison: tylko gdy klient wspomniał inne narzędzie (np. ChatGPT, Copilot, Lex, inny Legal AI). Inaczej zwróć dla niego {"hide": true} i nic więcej.
6. W nowej linii tytułu (title) używaj \n. W pozostałych polach nie łam linii.
7. Pisz z perspektywy odbiorcy (sekcja "Odbiorca prezentacji"): te same fakty ze zgłoszenia, ale akcenty, kolejność argumentów i ton dla tej roli. Wskazówki "For the <rola>:" w opisach pól są wiążące. Teksty domyślne są już napisane dla tej roli: gdy zgłoszenie nie daje podstawy, zostaw pole.
8. Fakty o produkcie (funkcje, efekty, dowody) bierz tylko z sekcji "Biblioteka"; nie wymyślaj funkcji spoza niej. use-areas: dla każdego obszaru najlepiej pasujące rozwiązanie z biblioteki. Ból z dopiskiem "brak w bibliotece": nie obiecuj jego rozwiązania. Typowe cytaty to słowa innych klientów: możesz ich użyć jako wskazówki, ale nigdy nie przypisuj ich temu klientowi.

Odpowiedz tylko poprawnym obiektem JSON (bez komentarzy i bez markdown). W tekstach nie używaj znaku " (cytaty pisz w ‘ ’). Zwracaj tylko pola, które piszesz:
{
  "slides": {
    "<klucz slajdu>": {
      "<pole tekstowe>": "…",
      "<pole listy>": [{"title": "…", "value": "…"}]
    },
    "tool-comparison": {"hide": true}
  }
}

